function isWhitelistedUrl(url) {
  if (!url) return false;
  const u = url.toLowerCase();
  return u.includes('marcaopersonal.com') || u.includes('shopee.com.br') || u.includes('s.shopee.com.br') || u.includes('wa.me') || u.includes('braip.com') || u.includes('ev.braip.com') || u.includes('stripe.com');
