function devePesquisarNaWeb(texto) {
  if (!texto) return false;
  let t = texto.trim().toLowerCase().replace(/[!?,;.]+/g, ' ').replace(/\s+/g, ' ').trim();
  const palavras = t.split(' ').filter(w => w.length > 0);
  if (palavras.length <= 2) return false;
  const termosPergunta = /\b(o que|oq|qual|quais|como|por que|pq|quanto|quantos|onde|quando|explica|funciona|estudo|serve para)\b/i.test(t);
  return termosPergunta || (texto.includes('?') && palavras.length >= 3);
}

