function detectarGenero(u, n) {
  u = (u || '').toLowerCase().replace(/[^a-z0-9_]/g, '');
  n = (n || '').toLowerCase().trim();

  const nomesFem = new Set([
    'eva', 'maria', 'ana', 'juliana', 'bruna', 'beatriz', 'camila', 'amanda', 
